$ErrorActionPreference='Stop'
function Edit-BsdfGuide([string]$path,[scriptblock]$edit){ $text=Get-Content -Raw -LiteralPath $path; $text=& $edit $text; Set-Content -LiteralPath $path -Value $text -NoNewline -Encoding utf8 }
Edit-BsdfGuide 'docs/STAROPT_FILE_FORMAT.md' { param($t) $t.Replace('**2 / 最大 10 / 6**','**2 / 最大 11 / 6**').Replace('声明商业格式或固定轴 BSDF 的工程（含禁用对象）写 v10，原各向同性 CSV v1 实测 BSDF 写 v9','声明投影 BSDF 或 Zemax 镜面中心表格的工程（含禁用对象）写 v11；原商业文本/固定轴 BSDF 写 v10，各向同性 CSV v1 实测 BSDF 写 v9').Replace('v1–10','v1–11').Replace('v8/v9/v10','v8/v9/v10/v11').Replace('当前工程负载最大版本为 10','当前工程负载最大版本为 11').Replace('v10 保存商业格式转换后的 BSDF','v11 保存投影数量类型、Zemax 原始镜面中心角表/TIS、测量波长及介质声明。v10 保存商业格式转换后的 BSDF').Replace('负载按商业或固定轴/原实测 v1/Lambertian/无 BSDF 选择 v10/v9/v8/v7','负载按投影或 Zemax/原商业文本或固定轴/原实测 v1/Lambertian/无 BSDF 选择 v11/v10/v9/v8/v7').Replace('模型及兼容边界见 [商业 BSDF 与固定轴](COMMERCIAL_BSDF_AXES_2026-10-31.md)','模型及兼容边界见 [二进制与 Zemax BSDF](BINARY_ZEMAX_BSDF_2026-10-31.md)') }
Edit-BsdfGuide 'docs/FILE_FORMATS_AND_PLUGINS.md' { param($t) $t.Replace('非序列 BSDF/BTDF 支持自有 CSV v1/v2 和 Speos v8 TEXT 的 .brdf/.anisotropicbsdf；商业或固定轴数据写 STAROPT v10','非序列 BSDF/BTDF 支持自有 CSV v1/v2、Speos v8 TEXT、已核验 archive-3 的 .brdf v8 与 .anisotropicbsdf v7/v9 二进制，以及显式波长/辐射度声明的 Zemax Monochrome .BSDF；投影数量或 Zemax 模型写 STAROPT v11，原商业文本/固定轴数据写 v10').Replace('尚无 Speos 二进制/强度、Zemax .BSDF、XYZ 光度、ASTM 或 Radiance XML 的直接导入。','新入口、角度/数量类型和预算见[二进制与 Zemax 契约](BINARY_ZEMAX_BSDF_2026-10-31.md)。尚无 Speos v11/未知二进制布局、活动增强/White Specular、XYZ 光度、ASTM 或 Radiance XML 的直接导入。') }
Edit-BsdfGuide 'docs/CAMERA_IMAGING_LAB.md' { param($t) $t.Replace('已接入实测 CSV 网格与 Speos v8 文本 BSDF/BTDF、固定材料轴各向异性','已接入实测 CSV、Speos v8 文本与已核验二进制 BSDF/BTDF、Zemax 单色辐射度 .BSDF 和固定材料轴各向异性').Replace('实测 CSV/Speos v8 TEXT BSDF/BTDF 与固定材料轴已接通','实测 CSV/Speos 文本及二进制、Zemax 单色 BSDF/BTDF 与固定材料轴已接通').Replace('已接入对象级 Lambertian、实测 CSV/Speos v8 文本 BSDF/BTDF 与固定材料轴','已接入对象级 Lambertian、实测 CSV/Speos 文本与已核验二进制 BSDF/BTDF、Zemax 单色辐射度 .BSDF 及固定材料轴').Replace('其他商业 BSDF 格式（现支持 Speos v8 TEXT 两类）','其他商业 BSDF 格式（现支持 Speos v8 TEXT、部分二进制版本及 Zemax 单色辐射度）').Replace('散射模型、文件约定、采样与能量验收见[专项说明](COMMERCIAL_BSDF_AXES_2026-10-31.md)','散射模型、文件约定、波长/辐射度声明、采样与能量验收见[专项说明](BINARY_ZEMAX_BSDF_2026-10-31.md)') }
Edit-BsdfGuide 'docs/NON_SEQUENTIAL_TRACING.md' { param($t) $t.Replace('[实测 CSV 与 Speos v8 文本 BSDF](COMMERCIAL_BSDF_AXES_2026-10-31.md)','[实测 CSV、Speos 文本/已核验二进制与 Zemax 单色 BSDF](BINARY_ZEMAX_BSDF_2026-10-31.md)').Replace('商业文件显式指定入射侧，固定材料轴以对象局部 XYZ 定义','商业文件显式指定入射侧；Zemax 须声明测量波长、原数据为辐射度及 BTDF 介质，固定材料轴以对象局部 XYZ 定义') }
Edit-BsdfGuide 'docs/NONSEQUENTIAL_PHASE2_STRAY_LIGHT.md' { param($t) $t.Replace('当前仍未实现：STEP/IGES/SAT导入','另已增加[Speos 二进制与 Zemax 单色辐射度导入](BINARY_ZEMAX_BSDF_2026-10-31.md)，保留镜面中心分布和投影数量，接入同一传感器。当前仍未实现：STEP/IGES/SAT导入') }
Edit-BsdfGuide 'docs/NONSEQUENTIAL_ZEMAX_PARITY_ROADMAP.md' { param($t) $t.Replace('其他商业格式与商业数值对标仍未完成','[已核验 Speos 二进制与 Zemax 单色辐射度格式](BINARY_ZEMAX_BSDF_2026-10-31.md)已接通；其他格式与商业数值对标仍未完成').Replace('已增加 Speos v8 TEXT 两类格式及固定轴各向异性','已增加 Speos v8 TEXT 两类、已核验二进制、Zemax 单色辐射度格式及固定轴各向异性') }
Edit-BsdfGuide 'docs/README.md' { param($t) $t.Replace('- [商业 BSDF 文本、固定材料轴与相机链路](COMMERCIAL_BSDF_AXES_2026-10-31.md)','- [商业 BSDF 文本、固定材料轴与相机链路](COMMERCIAL_BSDF_AXES_2026-10-31.md)'+[Environment]::NewLine+'- [Speos 二进制、Zemax 镜面中心 BSDF 与相机链路](BINARY_ZEMAX_BSDF_2026-10-31.md)') }
Edit-BsdfGuide 'docs/COMMERCIAL_BSDF_AXES_2026-10-31.md' { param($t) $t.Replace('## 文件和操作','本阶段记录文本格式与固定轴的原始实现及 156 项回归。后续已增加部分 Speos 二进制和 Zemax 单色辐射度 .BSDF，当前范围见[下一阶段](BINARY_ZEMAX_BSDF_2026-10-31.md)；下文保留原阶段边界。'+[Environment]::NewLine+[Environment]::NewLine+'## 本阶段文件和操作') }
Edit-BsdfGuide 'docs/BINARY_ZEMAX_BSDF_2026-10-31.md' { param($t) $t.Replace('官方资料指出 Monochrome 可代表光度 Y','[官方资料](https://optics.ansys.com/hc/en-us/articles/43071107687699-Zemax-Tabular-BSDF-data-file-format)指出 Monochrome 可代表光度 Y').Replace('它与 OpticStudio 文档中的部分近邻/随机方向插值策略不同','它与 [OpticStudio 文档](https://optics.ansys.com/hc/en-us/articles/43071089490451-How-to-use-tabular-BSDF-data-to-define-the-surface-scattering-distribution)中的部分近邻/随机方向插值策略不同').Replace('仍受总节点预算约束','仍受 TIS 总项≤6400 和总节点预算约束') }
